        return response
    elif request.url.path == "/echo_cookies":
        cookies = request.headers.get("cookie")
        response = httpx.Response(200, json={"cookies": cookies})
        return response
    else:
        return httpx.Response(404)

class MockTransportWithCookies(httpx.MockTransport):
